static void put(const char *name, const unsigned char *b, size_t n)
{
    char p[160]; snprintf(p, sizeof p, "sd/data/Pictures/%s", name);
    FILE *f = fopen(p, "wb");
    if (f) { fwrite(b, 1, n, f); fclose(f); }
}

